package com.bank.order;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Produces a valid execution order of onboarding steps (topological sort).
public class OnboardingPlanner {

    private static final Logger log = Logger.getLogger(OnboardingPlanner.class.getName());

    public int[] findOrder(int numSteps, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numSteps; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[numSteps];
        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);
            inDegree[p[0]]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numSteps; i++) {
            if (inDegree[i] == 0) queue.add(i);
        }

        int[] order = new int[numSteps];
        int idx = 0;
        while (!queue.isEmpty()) {
            int step = queue.poll();
            order[idx++] = step;             // emit as it unlocks
            for (int next : adj.get(step)) {
                if (--inDegree[next] == 0) queue.add(next);
            }
        }

        if (idx != numSteps) {               // cycle blocked some step
            log.info("Cycle detected; no valid order");
            return new int[0];
        }
        log.info("Valid order: " + Arrays.toString(order));
        return order;
    }
}
