package com.bank.order;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PlannerDemo {

    private static final Logger log = Logger.getLogger(PlannerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Onboarding Execution Plan");
        OnboardingPlanner planner = new OnboardingPlanner();

        // 4 steps: 1 after 0, 2 after 0, 3 after 1 and 2
        int[][] prereqs = {{1, 0}, {2, 0}, {3, 1}, {3, 2}};
        planner.findOrder(4, prereqs);              // e.g. [0,1,2,3]

        // cyclic → empty
        planner.findOrder(2, new int[][]{{1, 0}, {0, 1}});
    }
}
